package com.ecoriego.app.adapter; import android.view.*;import android.widget.*;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.ecoriego.app.R;import com.ecoriego.app.model.Riego;import java.util.*;
public class RiegoAdapter extends RecyclerView.Adapter<RiegoAdapter.VH>{List<Riego>d;public RiegoAdapter(List<Riego>x){d=x;}public void setData(List<Riego>x){d=x;notifyDataSetChanged();}@NonNull public VH onCreateViewHolder(@NonNull ViewGroup p,int v){return new VH(LayoutInflater.from(p.getContext()).inflate(R.layout.item_riego,p,false));}public void onBindViewHolder(@NonNull VH h,int i){Riego r=d.get(i);h.f.setText(r.getFechaHora());h.c.setText(String.format(Locale.getDefault(),"%.1f°C · Lluvia: %s",r.getTemperatura(),r.isLlovio()?"sí":"no"));}public int getItemCount(){return d.size();}static class VH extends RecyclerView.ViewHolder{TextView f,c;VH(View v){super(v);f=v.findViewById(R.id.tvFechaRiego);c=v.findViewById(R.id.tvClimaRiego);}}}
